def replace_max_specialchar(text, n):
    """Write a function to replace maximum n occurrences of spaces, commas, or dots with a colon."""
    if n <= 0:
        return text
    result = []
    replaced = 0
    for ch in text:
        if replaced < n and ch in (' ', ',', '.'):
            result.append(':')
            replaced += 1
        else:
            result.append(ch)
    return ''.join(result)
